 155→// runEnableInteractive runs the interactive enable flow.
 156→// agents must be provided by the caller (via detectOrSelectAgent).
 157→func runEnableInteractive(w io.Writer, agents []agent.Agent, localDev, useLocalSettings, useProjectSettings, forceHooks, skipPushSessions, telemetry bool) error {
 158→	// Uninstall hooks for agents that were previously active but are no longer selected
 159→	if err := uninstallDeselectedAgentHooks(w, agents); err != nil {
 160→		return fmt.Errorf("failed to clean up deselected agents: %w", err)
 161→	}
 162→
 163→	// Setup agent hooks for all selected agents
 164→	for _, ag := range agents {
 165→		if _, err := setupAgentHooks(ag, localDev, forceHooks); err != nil {
 166→			return fmt.Errorf("failed to setup %s hooks: %w", ag.Type(), err)
 167→		}
 168→	}
 169→
 170→	// Setup .entire directory
 171→	if _, err := setupEntireDirectory(); err != nil {
 172→		return fmt.Errorf("failed to setup .entire directory: %w", err)
 173→	}
 174→
 175→	// Load existing settings to preserve other options (like strategy_options.push)
 176→	settings, err := LoadEntireSettings()
 177→	if err != nil {
 178→		// If we can't load, start with defaults
 179→		settings = &EntireSettings{}
 180→	}
 181→	// Update the specific fields
 182→	settings.LocalDev = localDev
 183→	settings.Enabled = true
 184→
 185→	// Set push_sessions option if --skip-push-sessions flag was provided
 186→	if skipPushSessions {
 187→		if settings.StrategyOptions == nil {
 188→			settings.StrategyOptions = make(map[string]interface{})
 189→		}
 190→		settings.StrategyOptions["push_sessions"] = false
 191→	}
 192→
 193→	// Determine which settings file to write to
 194→	// First run always creates settings.json (no prompt)
 195→	entireDirAbs, err := paths.AbsPath(paths.EntireDir)
 196→	if err != nil {
 197→		entireDirAbs = paths.EntireDir // Fallback to relative
 198→	}
 199→	shouldUseLocal, showNotification := determineSettingsTarget(entireDirAbs, useLocalSettings, useProjectSettings)
 200→
 201→	if showNotification {
 202→		fmt.Fprintln(w, "Info: Project settings exist. Saving to settings.local.json instead.")
 203→		fmt.Fprintln(w, "  Use --project to update the project settings file.")
 204→	}
 205→
 206→	// Helper to save settings to the appropriate file
 207→	saveSettings := func() error {
 208→		if shouldUseLocal {
 209→			return SaveEntireSettingsLocal(settings)
 210→		}
 211→		return SaveEntireSettings(settings)
 212→	}
 213→
 214→	// Save settings before telemetry prompt so config is persisted even if the user cancels
 215→	if err := saveSettings(); err != nil {
 216→		return fmt.Errorf("failed to save settings: %w", err)
 217→	}
 218→
 219→	if _, err := strategy.InstallGitHook(true, localDev); err != nil {
 220→		return fmt.Errorf("failed to install git hooks: %w", err)
 221→	}
 222→	strategy.CheckAndWarnHookManagers(w, localDev)
 223→	fmt.Fprintln(w, "✓ Hooks installed")
 224→
 225→	configDisplay := configDisplayProject
 226→	if shouldUseLocal {
 227→		configDisplay = configDisplayLocal
 228→	}
 229→	fmt.Fprintf(w, "✓ Project configured (%s)\n", configDisplay)
 230→
 231→	// Ask about telemetry consent (only if not already asked)
 232→	fmt.Fprintln(w)
 233→	if err := promptTelemetryConsent(settings, telemetry); err != nil {
 234→		return fmt.Errorf("telemetry consent: %w", err)
 235→	}
 236→	// Save again to persist telemetry choice
 237→	if err := saveSettings(); err != nil {
 238→		return fmt.Errorf("failed to save settings: %w", err)
 239→	}
 240→
 241→	if err := strategy.EnsureSetup(); err != nil {
 242→		return fmt.Errorf("failed to setup strategy: %w", err)
 243→	}
 244→
 245→	fmt.Fprintln(w, "\nReady.")
 246→
 247→	return nil
 248→}
