 250→// runEnable is a simple enable that just sets the enabled flag (for programmatic use).
 251→func runEnable(w io.Writer) error {
 252→	settings, err := LoadEntireSettings()
 253→	if err != nil {
 254→		return fmt.Errorf("failed to load settings: %w", err)
 255→	}
 256→
 257→	settings.Enabled = true
 258→	if err := SaveEntireSettings(settings); err != nil {
 259→		return fmt.Errorf("failed to save settings: %w", err)
 260→	}
 261→
 262→	fmt.Fprintln(w, "Entire is now enabled.")
 263→	return nil
