 293→// checkDisabledGuard checks if Entire is disabled and prints a message if so.
 294→// Returns true if the caller should exit (i.e., Entire is disabled).
 295→// On error reading settings, defaults to enabled (returns false).
 296→func checkDisabledGuard(w io.Writer) bool {
 297→	enabled, err := IsEnabled()
 298→	if err != nil {
 299→		// Default to enabled on error
 300→		return false
 301→	}
 302→	if !enabled {
 303→		fmt.Fprintln(w, DisabledMessage)
 304→		return true
 305→	}
