 309→// uninstallDeselectedAgentHooks removes hooks for agents that were previously
 310→// installed but are not in the selected list. This handles the case where a user
 311→// re-runs `entire enable` and deselects an agent.
 312→func uninstallDeselectedAgentHooks(w io.Writer, selectedAgents []agent.Agent) error {
 313→	installedNames := GetAgentsWithHooksInstalled()
 314→	if len(installedNames) == 0 {
 315→		return nil
 316→	}
 317→
 318→	selectedSet := make(map[agent.AgentName]struct{}, len(selectedAgents))
 319→	for _, ag := range selectedAgents {
 320→		selectedSet[ag.Name()] = struct{}{}
 321→	}
 322→
 323→	var errs []error
 324→	for _, name := range installedNames {
 325→		if _, selected := selectedSet[name]; selected {
 326→			continue
 327→		}
 328→		ag, err := agent.Get(name)
 329→		if err != nil {
 330→			continue
 331→		}
 332→		hookAgent, ok := ag.(agent.HookSupport)
 333→		if !ok {
 334→			continue
 335→		}
 336→		if err := hookAgent.UninstallHooks(); err != nil {
 337→			errs = append(errs, fmt.Errorf("failed to uninstall %s hooks: %w", ag.Type(), err))
 338→		} else {
 339→			fmt.Fprintf(w, "Removed %s hooks\n", ag.Type())
 340→		}
 341→	}
 342→	return errors.Join(errs...)
 343→}
