 345→// setupAgentHooks sets up hooks for a given agent.
 346→// Returns the number of hooks installed (0 if already installed).
 347→func setupAgentHooks(ag agent.Agent, localDev, forceHooks bool) (int, error) {
 348→	hookAgent, ok := ag.(agent.HookSupport)
 349→	if !ok {
 350→		return 0, fmt.Errorf("agent %s does not support hooks", ag.Name())
 351→	}
 352→
 353→	count, err := hookAgent.InstallHooks(localDev, forceHooks)
 354→	if err != nil {
 355→		return 0, fmt.Errorf("failed to install %s hooks: %w", ag.Name(), err)
 356→	}
 357→
 358→	return count, nil
 359→}
