 361→// detectOrSelectAgent tries to auto-detect agents, or prompts the user to select.
 362→// Returns the detected/selected agents and any error.
 363→//
 364→// On first run (no hooks installed):
 365→//   - Single detected agent: used automatically
 366→//   - Multiple/no detected agents: interactive multi-select prompt
 367→//
 368→// On re-run (hooks already installed):
 369→//   - Always shows the interactive multi-select
 370→//   - Pre-selects only agents that have hooks installed (respects prior deselection)
 371→//
 372→// selectFn overrides the interactive prompt for testing. When nil, the real form is used.
 373→// It receives available agent names and returns the selected names.
 374→func detectOrSelectAgent(w io.Writer, selectFn func(available []string) ([]string, error)) ([]agent.Agent, error) {
 375→	// Check for agents with hooks already installed (re-run detection)
 376→	installedAgentNames := GetAgentsWithHooksInstalled()
 377→	hasInstalledHooks := len(installedAgentNames) > 0
 378→
 379→	// Try auto-detection
 380→	detected := agent.DetectAll()
 381→
 382→	// First run: use existing auto-detect shortcuts
 383→	if !hasInstalledHooks {
 384→		switch {
 385→		case len(detected) == 1:
 386→			fmt.Fprintf(w, "Detected agent: %s\n\n", detected[0].Type())
 387→			return detected, nil
 388→
 389→		case len(detected) > 1:
 390→			agentTypes := make([]string, 0, len(detected))
 391→			for _, ag := range detected {
 392→				agentTypes = append(agentTypes, string(ag.Type()))
 393→			}
 394→			fmt.Fprintf(w, "Detected multiple agents: %s\n", strings.Join(agentTypes, ", "))
 395→			fmt.Fprintln(w)
 396→		}
 397→	}
 398→
 399→	// Check if we can prompt interactively
 400→	if !canPromptInteractively() {
 401→		if hasInstalledHooks {
 402→			// Re-run without TTY — keep currently installed agents
 403→			agents := make([]agent.Agent, 0, len(installedAgentNames))
 404→			for _, name := range installedAgentNames {
 405→				ag, err := agent.Get(name)
 406→				if err != nil {
 407→					continue
 408→				}
 409→				agents = append(agents, ag)
 410→			}
 411→			return agents, nil
 412→		}
 413→		if len(detected) > 0 {
 414→			return detected, nil
 415→		}
 416→		defaultAgent := agent.Default()
 417→		if defaultAgent == nil {
 418→			return nil, errors.New("no default agent available")
 419→		}
 420→		fmt.Fprintf(w, "Agent: %s (use --agent to change)\n\n", defaultAgent.Type())
 421→		return []agent.Agent{defaultAgent}, nil
 422→	}
 423→
 424→	if !hasInstalledHooks && len(detected) == 0 {
 425→		fmt.Fprintln(w, "No agent configuration detected (e.g., .claude, .gemini, or .opencode directory).")
 426→		fmt.Fprintln(w, "This is normal - some agents don't require a config directory.")
 427→		fmt.Fprintln(w)
 428→	}
 429→
 430→	// Build pre-selection set.
 431→	// On re-run: only pre-select agents with hooks installed (respect prior deselection).
 432→	// On first run: pre-select all detected agents.
 433→	preSelectedSet := make(map[agent.AgentName]struct{})
 434→	if hasInstalledHooks {
 435→		for _, name := range installedAgentNames {
 436→			preSelectedSet[name] = struct{}{}
 437→		}
 438→	} else {
 439→		for _, ag := range detected {
 440→			preSelectedSet[ag.Name()] = struct{}{}
 441→		}
 442→	}
 443→
 444→	// Build options from registered agents
 445→	agentNames := agent.List()
 446→	options := make([]huh.Option[string], 0, len(agentNames))
 447→	for _, name := range agentNames {
 448→		ag, err := agent.Get(name)
 449→		if err != nil {
 450→			continue
 451→		}
 452→		// Only show agents that support hooks
 453→		if _, ok := ag.(agent.HookSupport); !ok {
 454→			continue
 455→		}
 456→		opt := huh.NewOption(string(ag.Type()), string(name))
 457→		if _, isPreSelected := preSelectedSet[name]; isPreSelected {
 458→			opt = opt.Selected(true)
 459→		}
 460→		options = append(options, opt)
 461→	}
 462→
 463→	if len(options) == 0 {
 464→		return nil, errors.New("no agents with hook support available")
 465→	}
 466→
 467→	// Collect available agent names for the selector
 468→	availableNames := make([]string, 0, len(options))
 469→	for _, opt := range options {
 470→		availableNames = append(availableNames, opt.Value)
 471→	}
 472→
 473→	var selectedAgentNames []string
 474→	if selectFn != nil {
 475→		var err error
 476→		selectedAgentNames, err = selectFn(availableNames)
 477→		if err != nil {
 478→			return nil, err
 479→		}
 480→		if len(selectedAgentNames) == 0 {
 481→			return nil, errors.New("no agents selected")
 482→		}
 483→	} else {
 484→		form := NewAccessibleForm(
 485→			huh.NewGroup(
 486→				huh.NewMultiSelect[string]().
 487→					Title("Which agents are you using?").
 488→					Description("Use space to select, enter to confirm.").
 489→					Options(options...).
 490→					Validate(func(selected []string) error {
 491→						if len(selected) == 0 {
 492→							return errors.New("please select at least one agent")
 493→						}
 494→						return nil
 495→					}).
 496→					Value(&selectedAgentNames),
 497→			),
 498→		)
 499→		if err := form.Run(); err != nil {
 500→			return nil, fmt.Errorf("agent selection cancelled: %w", err)
 501→		}
 502→	}
 503→
 504→	selectedAgents := make([]agent.Agent, 0, len(selectedAgentNames))
 505→	for _, name := range selectedAgentNames {
 506→		selectedAgent, err := agent.Get(agent.AgentName(name))
 507→		if err != nil {
 508→			return nil, fmt.Errorf("failed to get selected agent %s: %w", name, err)
 509→		}
 510→		selectedAgents = append(selectedAgents, selectedAgent)
 511→	}
 512→
 513→	agentTypes := make([]string, 0, len(selectedAgents))
 514→	for _, ag := range selectedAgents {
 515→		agentTypes = append(agentTypes, string(ag.Type()))
 516→	}
 517→	fmt.Fprintf(w, "\nSelected agents: %s\n\n", strings.Join(agentTypes, ", "))
 518→	return selectedAgents, nil
 519→}
