 521→// canPromptInteractively checks if we can show interactive prompts.
 522→// Returns false when running in CI, tests, or other non-interactive environments.
 523→func canPromptInteractively() bool {
 524→	// Check for test environment
 525→	if os.Getenv("ENTIRE_TEST_TTY") != "" {
 526→		return os.Getenv("ENTIRE_TEST_TTY") == "1"
 527→	}
 528→
 529→	// Check if /dev/tty is available
 530→	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
 531→	if err != nil {
 532→		return false
 533→	}
 534→	_ = tty.Close()
 535→	return true
 536→}
