 839→// isCompletionConfigured checks if shell completion is already in the rc file.
 840→func isCompletionConfigured(rcFile string) bool {
 841→	//nolint:gosec // G304: rcFile is constructed from home dir + known filename, not user input
 842→	content, err := os.ReadFile(rcFile)
 843→	if err != nil {
 844→		return false // File doesn't exist or can't read, treat as not configured
 845→	}
 846→	return strings.Contains(string(content), "entire completion")
 847→}
