1066→		wasInstalled := hs.AreHooksInstalled()
1067→		if err := hs.UninstallHooks(); err != nil {
1068→			errs = append(errs, err)
1069→		} else if wasInstalled {
1070→			fmt.Fprintf(w, "  Removed %s hooks\n", ag.Type())
1071→		}
1072→	}
1073→	return errors.Join(errs...)
1074→}
